import { CursorPosition, Order } from './types';

function compareOrderPositions(
  a: { createdAt: string; id: string },
  b: { createdAt: string; id: string }
): number {
  if (a.createdAt < b.createdAt) return -1;
  if (a.createdAt > b.createdAt) return 1;
  if (a.id < b.id) return -1;
  if (a.id > b.id) return 1;
  return 0;
}

export class OrderRepository {
  constructor(private readonly rows: Order[]) {}

  /**
   * Returns the tenant's orders sorted ascending by (createdAt, id).
   * When `after` is given, only orders strictly after that position are
   * returned; the position itself does not need to exist in the data.
   * Never mutates the input array or the stored rows.
   */
  list(tenant: string, after?: CursorPosition, limit?: number): Order[] {
    const matching = this.rows.filter(row => row.tenant === tenant);
    matching.sort(compareOrderPositions);

    let start = 0;
    if (after) {
      const found = matching.findIndex(row => compareOrderPositions(row, after) > 0);
      start = found === -1 ? matching.length : found;
    }

    if (limit === undefined) {
      return matching.slice(start);
    }
    return matching.slice(start, start + Math.max(limit, 0));
  }
}
