import { OrderRepository } from './repository';
import { CursorPosition, ListRequest, Page } from './types';

function parseCursor(cursor: string | undefined): CursorPosition | undefined {
  if (cursor === undefined) return undefined;
  const parts = typeof cursor === 'string' ? cursor.split('|') : [];
  if (parts.length !== 2 || parts[0] === '' || parts[1] === '') {
    throw new Error('invalid request');
  }
  return { createdAt: parts[0], id: parts[1] };
}

function cursorOf(order: { createdAt: string; id: string }): string {
  return `${order.createdAt}|${order.id}`;
}

export class OrderHandler {
  constructor(private readonly repository: OrderRepository) {}

  list(request: ListRequest): Page {
    if (!request.tenant || !Number.isInteger(request.limit) || request.limit < 1 || request.limit > 100) {
      throw new Error('invalid request');
    }
    const after = parseCursor(request.cursor);
    // Fetch one extra row to know whether another page exists.
    const items = this.repository.list(request.tenant, after, request.limit + 1);
    const hasMore = items.length > request.limit;
    const page = hasMore ? items.slice(0, request.limit) : items;
    return {
      items: page,
      nextCursor: hasMore && page.length > 0 ? cursorOf(page[page.length - 1]) : null
    };
  }
}
